import classes from './MealsSummarymodule.css';
const MealsSummary = ()=>{
    return(
        <section className={classes.MealsSummary}>
            <h2>Delicious Food,Delivered To You</h2>
            <p>
                Choose your favourite meal from our broad section of available meals and enjoy and
                 a delicious lunch or dinner at home.
           </p>
          <p>
             All our meals are cooked with high-quality   ingredients,just-in-time and of course by
          experienced chefs!
         </p> 
     </section>
    )
}
export default MealsSummary;
